    assert tax_for(1000, Decimal("0.0825")) == 82
    assert isinstance(tax_for(1000, Decimal("0.0825")), int)


def test_tax_for_rounds_half_even():
    assert tax_for(250, Decimal("0.01")) == 2  # 2.5 -> 2
    assert tax_for(350, Decimal("0.01")) == 4  # 3.5 -> 4


def test_tax_for_accepts_float_rate():
